import * as crypto from 'node:crypto'
import * as fs from 'node:fs'
import * as path from 'node:path'
import type { ArtifactKind } from '../config.js'

/**
 * Standard auto-generated banner markers used for Gate 3 safety verification.
 */
export const DEFAULT_BANNER_MARKERS: readonly string[] = [
  '@generated',
  'Generated by @oa-sdk',
  'Auto-generated by oa-sdk',
  '@oa-sdk/codegen',
  'DO NOT EDIT',
  'This file is auto-generated',
]

/**
 * `producer` values that `oa-gen` commands record in `.oa-manifest.json`: the
 * name of the command that wrote the artifact.
 */
export const MANIFEST_PRODUCERS = {
  generate: 'generate',
  generateTanstack: 'generate:tanstack',
} as const

/**
 * Manifest record representing a single generated artifact on disk.
 */
export interface ManifestArtifact {
  /** Relative path from rootDir, POSIX normalized */
  path: string
  /** Artifact kind (contract, client, queries, keys, guards, schemas) */
  kind: ArtifactKind
  /** Routing tag the path was dispatched with. `oa-gen generate` sets it to the spec target id. */
  tag?: string | undefined
  /**
   * Command that wrote the artifact (see `MANIFEST_PRODUCERS`). Records written
   * before codegen 0.9.0 have none; `manifestArtifactOwner` infers it for them.
   */
  producer?: string | undefined
  /**
   * Configuration file of the run that wrote the artifact, relative to rootDir
   * (POSIX). Absent when that run read no configuration file.
   */
  configFile?: string | undefined
  /** Spec target id (`specs[].id`) the artifact was generated for. Absent for artifacts of no single target. */
  target?: string | undefined
  /** SHA-256 content hash ("sha256:...") */
  contentHash: string
  /** Source OpenAPI specification path or fingerprint */
  sourceSpec?: string | undefined
  /** Generation timestamp (ISO string) */
  generatedAt: string
}

/**
 * Who wrote a manifest record, which decides the runs that may prune it.
 */
export interface ManifestArtifactOwner {
  /** Command that wrote the record, or undefined when it cannot be told. */
  producer: string | undefined
  /** Configuration file of that run, relative to rootDir. Undefined when the run read none, or when `legacy`. */
  configFile: string | undefined
  /** Spec target id the record belongs to, if any. */
  target: string | undefined
  /** True for a record written before codegen 0.9.0: its owner is inferred and its configuration file is unknown. */
  legacy: boolean
}

/**
 * Owner of a manifest record.
 *
 * Records written before codegen 0.9.0 carry no `producer`. Their writers are
 * known: only `oa-gen generate` set `tag` (always to the spec target id) and
 * only it wrote `guards` records, while `oa-gen generate:tanstack` set neither.
 * A legacy record with a `tag` is therefore owned by `oa-gen generate` for that
 * target, a legacy `guards` record by `oa-gen generate` for no single target,
 * and any other legacy record by an unknown producer.
 */
export function manifestArtifactOwner(artifact: ManifestArtifact): ManifestArtifactOwner {
  if (artifact.producer !== undefined) {
    return { producer: artifact.producer, configFile: artifact.configFile, target: artifact.target, legacy: false }
  }
  if (artifact.tag !== undefined) {
    return { producer: MANIFEST_PRODUCERS.generate, configFile: undefined, target: artifact.tag, legacy: true }
  }
  if (artifact.kind === 'guards') {
    return { producer: MANIFEST_PRODUCERS.generate, configFile: undefined, target: undefined, legacy: true }
  }
  return { producer: undefined, configFile: undefined, target: undefined, legacy: true }
}

/**
 * Root schema for .oa-manifest.json.
 */
export interface OaManifest {
  $schema?: string | undefined
  version: number
  generator: string
  lastRun: string
  specFingerprint?: string | undefined
  artifacts: ManifestArtifact[]
}

/**
 * Input descriptor for writing an artifact.
 */
export interface WriteArtifactInput {
  /** File path (relative to rootDir or absolute) */
  path: string
  /** Artifact kind */
  kind: ArtifactKind
  /** Source code content to write */
  content: string
  /** Routing tag the path was dispatched with */
  tag?: string | undefined
  /** Command that writes the artifact (see `MANIFEST_PRODUCERS`) */
  producer?: string | undefined
  /** Configuration file of the run, relative to rootDir (POSIX) */
  configFile?: string | undefined
  /** Spec target id the artifact is generated for */
  target?: string | undefined
  /** Source OpenAPI spec path */
  sourceSpec?: string | undefined
}

/**
 * Result of writing a batch of artifacts.
 */
export interface WriteArtifactResult {
  /** List of file paths actually written/updated to disk */
  written: string[]
  /** List of file paths skipped because disk content was already bit-identical */
  skipped: string[]
  /** Updated manifest object */
  manifest: OaManifest
}

/**
 * Record of an artifact skipped during orphan pruning due to safety invariants.
 */
export interface PruneSkippedEntry {
  path: string
  reason: 'provenance-missing' | 'content-modified' | 'banner-missing' | 'file-not-found'
  detail: string
}

/**
 * Options of an orphan pruning execution.
 */
export interface PruneOrphansOptions {
  /** Reports what would be pruned without deleting files or saving the manifest */
  dryRun?: boolean | undefined
  /** Directory at which removal of emptied parent directories stops (defaults to rootDir) */
  baseDir?: string | undefined
  /**
   * Records this execution may prune. A record outside the scope is never a
   * candidate: its file is not deleted and the record stays in the manifest.
   * Defaults to every record.
   */
  scope?: ((artifact: ManifestArtifact) => boolean) | undefined
}

/**
 * Result of an orphan pruning execution.
 */
export interface PruneResult {
  /** List of obsolete artifact paths safely deleted */
  pruned: string[]
  /** List of candidate paths skipped due to safety gates */
  skipped: PruneSkippedEntry[]
  /** List of empty parent directories removed */
  removedDirs: string[]
}

/**
 * Normalizes a path string to POSIX format.
 */
function toPosix(filePath: string): string {
  return filePath.replace(/\\/g, '/')
}

/**
 * Manages the lifecycle of generated artifacts via `.oa-manifest.json`.
 * Enforces the 3-Gate Safety Invariants (Provenance, Hash Integrity, Banner Guard)
 * to safely prune obsolete generated artifacts while guaranteeing hand-written developer
 * files are never deleted or modified.
 */
export class OaManifestManager {
  public readonly rootDir: string
  public readonly manifestPath: string
  public readonly bannerMarkers: string[]
  private manifest: OaManifest | null = null

  public constructor(
    rootDir: string = process.cwd(),
    manifestPath?: string,
    bannerMarkers: string[] = [...DEFAULT_BANNER_MARKERS],
  ) {
    this.rootDir = path.resolve(rootDir)
    this.manifestPath = manifestPath
      ? path.isAbsolute(manifestPath)
        ? manifestPath
        : path.resolve(this.rootDir, manifestPath)
      : path.resolve(this.rootDir, '.oa-manifest.json')
    this.bannerMarkers = bannerMarkers
  }

  /**
   * Computes the SHA-256 content hash formatted as "sha256:<hex>".
   */
  public computeHash(content: string): string {
    const hex = crypto.createHash('sha256').update(content, 'utf8').digest('hex')
    return `sha256:${hex}`
  }

  /**
   * Loads the existing manifest from disk or initializes a fresh manifest structure.
   */
  public async loadManifest(): Promise<OaManifest> {
    try {
      if (fs.existsSync(this.manifestPath)) {
        const raw = await fs.promises.readFile(this.manifestPath, 'utf8')
        this.manifest = JSON.parse(raw) as OaManifest
        return this.manifest
      }
    } catch {
      // If reading/parsing fails, fallback to fresh manifest
    }

    this.manifest = {
      $schema: 'https://oa-sdk.dev/schemas/v1/oa-manifest.schema.json',
      version: 1,
      generator: '@oa-sdk/codegen',
      lastRun: new Date().toISOString(),
      artifacts: [],
    }
    return this.manifest
  }

  /**
   * Returns the cached manifest or loads it synchronously if not yet loaded.
   */
  public getManifest(): OaManifest {
    if (!this.manifest) {
      if (fs.existsSync(this.manifestPath)) {
        try {
          const raw = fs.readFileSync(this.manifestPath, 'utf8')
          this.manifest = JSON.parse(raw) as OaManifest
          return this.manifest
        } catch {
          // fallback
        }
      }
      this.manifest = {
        $schema: 'https://oa-sdk.dev/schemas/v1/oa-manifest.schema.json',
        version: 1,
        generator: '@oa-sdk/codegen',
        lastRun: new Date().toISOString(),
        artifacts: [],
      }
    }
    return this.manifest
  }

  /**
   * Atomically saves the manifest file to disk using a temporary file rename.
   */
  public async saveManifest(manifest?: OaManifest): Promise<void> {
    const data = manifest ?? this.manifest ?? (await this.loadManifest())
    data.lastRun = new Date().toISOString()
    this.manifest = data

    await fs.promises.mkdir(path.dirname(this.manifestPath), { recursive: true })
    const tmpPath = `${this.manifestPath}.tmp.${Date.now()}`

    await fs.promises.writeFile(tmpPath, JSON.stringify(data, null, 2) + '\n', 'utf8')
    await fs.promises.rename(tmpPath, this.manifestPath)
  }

  /**
   * Writes a collection of generated artifacts to disk safely.
   * If a file already exists on disk with identical SHA-256 hash, writing is skipped
   * to preserve filesystem timestamps for incremental build tools.
   */
  public async writeArtifacts(
    artifacts: WriteArtifactInput[],
    options: { dryRun?: boolean; specFingerprint?: string } = {},
  ): Promise<WriteArtifactResult> {
    const manifest = await this.loadManifest()
    if (options.specFingerprint) {
      manifest.specFingerprint = options.specFingerprint
    }

    const written: string[] = []
    const skipped: string[] = []
    const artifactMap = new Map<string, ManifestArtifact>()

    // Seed existing artifacts map
    for (const art of manifest.artifacts) {
      artifactMap.set(toPosix(art.path), art)
    }

    for (const art of artifacts) {
      const absPath = path.isAbsolute(art.path) ? art.path : path.resolve(this.rootDir, art.path)
      const relPath = toPosix(path.relative(this.rootDir, absPath))
      const contentHash = this.computeHash(art.content)

      let shouldWrite = true
      if (fs.existsSync(absPath)) {
        try {
          const diskContent = await fs.promises.readFile(absPath, 'utf8')
          const diskHash = this.computeHash(diskContent)
          if (diskHash === contentHash) {
            shouldWrite = false
            skipped.push(relPath)
          }
        } catch {
          shouldWrite = true
        }
      }

      if (shouldWrite) {
        if (!options.dryRun) {
          await fs.promises.mkdir(path.dirname(absPath), { recursive: true })
          await fs.promises.writeFile(absPath, art.content, 'utf8')
        }
        written.push(relPath)
      }

      // Record in manifest
      artifactMap.set(relPath, {
        path: relPath,
        kind: art.kind,
        ...(art.tag ? { tag: art.tag } : {}),
        ...(art.producer ? { producer: art.producer } : {}),
        ...(art.configFile ? { configFile: art.configFile } : {}),
        ...(art.target ? { target: art.target } : {}),
        contentHash,
        ...(art.sourceSpec ? { sourceSpec: art.sourceSpec } : {}),
        generatedAt: new Date().toISOString(),
      })
    }

    manifest.artifacts = Array.from(artifactMap.values())
    if (!options.dryRun) {
      await this.saveManifest(manifest)
    }

    return { written, skipped, manifest }
  }

  /**
   * Evaluates candidate files for orphan pruning using the 3-Gate Safety Invariants:
   * 1. Gate 1 (Manifest Provenance): Must be recorded in the manifest, within `options.scope`.
   * 2. Gate 2 (Content Hash Integrity): Disk SHA-256 must match manifest hash (unmodified by developer).
   * 3. Gate 3 (Banner Verification): File on disk must contain an auto-generated banner.
   */
  public async pruneOrphans(
    activeRelativePaths: string[] | Set<string>,
    options: PruneOrphansOptions = {},
  ): Promise<PruneResult> {
    const manifest = await this.loadManifest()
    const activeSet = new Set(
      Array.from(activeRelativePaths).map((p) => toPosix(path.normalize(p))),
    )

    const pruned: string[] = []
    const skipped: PruneSkippedEntry[] = []
    const removedDirs: string[] = []

    const remainingArtifacts: ManifestArtifact[] = []

    for (const recorded of manifest.artifacts) {
      const posixPath = toPosix(recorded.path)

      // Outside this execution's scope, or still active in the current generation run -> keep
      if ((options.scope && !options.scope(recorded)) || activeSet.has(posixPath)) {
        remainingArtifacts.push(recorded)
        continue
      }

      // Candidate orphan: apply 3-Gate Safety Invariants
      const absPath = path.resolve(this.rootDir, posixPath)

      if (!fs.existsSync(absPath)) {
        // Obsolete file already deleted externally; safely remove from manifest
        skipped.push({
          path: posixPath,
          reason: 'file-not-found',
          detail: 'File no longer exists on disk; pruned from manifest tracking.',
        })
        continue
      }

      let diskContent: string
      try {
        diskContent = await fs.promises.readFile(absPath, 'utf8')
      } catch (err) {
        skipped.push({
          path: posixPath,
          reason: 'content-modified',
          detail: `Cannot read file on disk: ${err instanceof Error ? err.message : String(err)}`,
        })
        remainingArtifacts.push(recorded)
        continue
      }

      // Gate 2: Content Hash Integrity Guard
      const diskHash = this.computeHash(diskContent)
      if (diskHash !== recorded.contentHash) {
        skipped.push({
          path: posixPath,
          reason: 'content-modified',
          detail: `Disk hash (${diskHash}) differs from recorded hash (${recorded.contentHash}). File was modified by developer.`,
        })
        remainingArtifacts.push(recorded)
        continue
      }

      // Gate 3: Auto-Generated Banner Verification
      const hasBanner = this.bannerMarkers.some((marker) => diskContent.includes(marker))
      if (!hasBanner) {
        skipped.push({
          path: posixPath,
          reason: 'banner-missing',
          detail: 'File on disk does not contain recognized auto-generated banner.',
        })
        remainingArtifacts.push(recorded)
        continue
      }

      // All 3 gates passed: Safe to prune!
      if (!options.dryRun) {
        try {
          await fs.promises.unlink(absPath)
          pruned.push(posixPath)

          // Clean empty parent directories up to baseDir or rootDir
          const stopDir = options.baseDir
            ? path.isAbsolute(options.baseDir)
              ? options.baseDir
              : path.resolve(this.rootDir, options.baseDir)
            : this.rootDir
          const cleaned = await this.cleanEmptyParentDirs(path.dirname(absPath), stopDir)
          removedDirs.push(...cleaned)
        } catch (err) {
          skipped.push({
            path: posixPath,
            reason: 'content-modified',
            detail: `Failed to unlink file: ${err instanceof Error ? err.message : String(err)}`,
          })
          remainingArtifacts.push(recorded)
        }
      } else {
        pruned.push(posixPath)
      }
    }

    manifest.artifacts = remainingArtifacts
    if (!options.dryRun) {
      await this.saveManifest(manifest)
    }

    return { pruned, skipped, removedDirs }
  }

  /**
   * Recursively removes empty parent directories up to stopDir.
   */
  private async cleanEmptyParentDirs(dir: string, stopDir: string): Promise<string[]> {
    const cleaned: string[] = []
    let current = path.resolve(dir)
    const resolvedStop = path.resolve(stopDir)

    while (current !== resolvedStop && current.startsWith(resolvedStop)) {
      try {
        const entries = await fs.promises.readdir(current)
        if (entries.length === 0) {
          await fs.promises.rmdir(current)
          cleaned.push(toPosix(path.relative(this.rootDir, current)))
          current = path.dirname(current)
        } else {
          break
        }
      } catch {
        break
      }
    }

    return cleaned
  }
}
